PROGRAM ST530_VERTIKALTRANSPORT
VAR
    steg        : INT := 0;
    tmrRes      : TON;
    trigReset   : R_TRIG;
    xLarm       : BOOL := FALSE;
    xKravOmstart: BOOL := TRUE;
    xDriftsklar : BOOL := FALSE;
    xRor        : BOOL := FALSE;
    xGrensle    : BOOL := FALSE;
    xUpp        : BOOL := FALSE; (* sekvensens kommando uppat *)
    xNer        : BOOL := FALSE; (* sekvensens kommando nedat *)
END_VAR

(* EMG_OK kommer fran sakerhets-PLC och lases bara. *)
trigReset(CLK := SYS_RESET);

IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* --- larmkallorna samlas fore domen --- *)

(* Slaglangden ar 0 till 3600 mm. Ett lage utanfor -40,0 till 3800,0 mm kan
   korgen inte sta i; da ar givaren eller dess skalning trasig, och en hiss som
   kors pa ett falskt lage kor in i sitt eget andstopp. *)
IF ST530_LFT_POS < -40.0 OR ST530_LFT_POS > 3800.0 THEN
    xLarm := TRUE;
END_IF;

(* Tidsvakt over resan. Trapetsprofilen ger 5,30 s over 3,6 m; vakten 7,0 s
   lamnar 1,70 s marginal. *)
xRor := ST530_LFT_UP OR ST530_LFT_DOWN;
tmrRes(IN := xRor, PT := T#7s);
IF tmrRes.Q THEN
    xLarm := TRUE;
END_IF;

(* Lastbararen bryter bada fotocellerna samtidigt: den hanger grensle over
   overlamningen mellan inmatningen och korgen. *)
xGrensle := ST530_PEC_CAR AND ST530_PEC_IN;

IF trigReset.Q AND EMG_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;
xDriftsklar := EMG_OK AND SYS_AUTO AND NOT xLarm AND NOT xKravOmstart;

IF NOT xDriftsklar THEN
    xUpp := FALSE;
    xNer := FALSE;
    ST530_CNV_IN := FALSE;
    ST530_CNV_OUT := FALSE;
    steg := 0;
ELSE
    CASE steg OF
        0:
            xUpp := FALSE;
            ST530_CNV_OUT := FALSE;
            (* Korgen ska sta nere och vanta pa nasta lastbarare. *)
            xNer := (NOT ST530_LFT_BOT) AND (NOT ST530_PEC_CAR);
            (* Ingen inmatning forran korgen star i sitt nedre andlage. *)
            IF ST530_PEC_IN AND ST530_LFT_BOT AND NOT ST530_PEC_CAR THEN
                ST530_CNV_IN := TRUE;
                steg := 1;
            ELSE
                ST530_CNV_IN := FALSE;
            END_IF;
        1:
            (* Lastbararen ar helt pa korgen forst nar den slappt inmatningens
               fotocell och bryter korgens. *)
            IF ST530_PEC_CAR AND NOT ST530_PEC_IN THEN
                ST530_CNV_IN := FALSE;
                steg := 2;
            END_IF;
        2:
            IF NOT xGrensle THEN
                xUpp := TRUE;
                steg := 3;
            END_IF;
        3:
            IF ST530_LFT_TOP THEN
                xUpp := FALSE;
                ST530_CNV_OUT := TRUE;
                steg := 4;
            END_IF;
        4:
            IF ST530_PEC_OUT AND NOT ST530_PEC_CAR THEN
                ST530_CNV_OUT := FALSE;
                xNer := TRUE;
                steg := 5;
            END_IF;
        5:
            IF ST530_LFT_BOT THEN
                xNer := FALSE;
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;

(* Omsesidig uteslutning skriven som villkor pa utgangen, inte som en foljd
   av stegen: korgen har en kontaktor per riktning och tva hoga signaler ar en
   kortslutning i stallet for en rorelse. Hissen ror sig aldrig heller med en
   lastbarare grensle over overlamningen. Varje utgang skrivs pa ETT stalle. *)
ST530_LFT_UP := xUpp AND NOT xNer AND NOT xGrensle;
ST530_LFT_DOWN := xNer AND NOT xUpp AND NOT xGrensle;

(* Ingen inmatning nar korgen inte star i sitt nedre andlage. *)
IF NOT ST530_LFT_BOT THEN
    ST530_CNV_IN := FALSE;
END_IF;
END_PROGRAM

